import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

export default function Register() {
  const [form, setForm] = useState({ name: '', email: '', password: '', confirm: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { register } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (form.password !== form.confirm) {
      setError('Passwords do not match');
      return;
    }
    setLoading(true);
    setError('');
    try {
      await register(form.name, form.email, form.password);
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.error || 'Registration failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-vh-100 d-flex align-items-center justify-content-center" style={{ background: 'linear-gradient(135deg,#4f46e5,#7c3aed)' }}>
      <div className="card card-mw shadow p-4" style={{ width: '100%', maxWidth: 420 }}>
        <h3 className="text-center mb-4">Create Account</h3>
        {error && <div className="alert alert-danger">{error}</div>}
        <form onSubmit={handleSubmit}>
          {['name', 'email', 'password', 'confirm'].map((f) => (
            <div className="mb-3" key={f}>
              <label className="form-label text-capitalize">{f === 'confirm' ? 'Confirm Password' : f}</label>
              <input
                type={f.includes('password') || f === 'confirm' ? 'password' : f === 'email' ? 'email' : 'text'}
                className="form-control"
                value={form[f]}
                onChange={(e) => setForm({ ...form, [f]: e.target.value })}
                required
              />
            </div>
          ))}
          <button className="btn btn-primary w-100" disabled={loading}>Register</button>
        </form>
        <p className="text-center mt-3"><Link to="/login">Already have an account?</Link></p>
      </div>
    </div>
  );
}
